/**
 * Wharf WharfSWE results: 14 C# tasks drawn from Wharf's own development history, four
 * attempts each (56 trials per run). A separate dataset from DeepSWE — never mix the two.
 *
 * The numbers live in wharf-swe.json, generated by `npm run wharf:sync -- <wharf checkout>`
 * from wharf-swe/data/manifest.json. Don't edit the JSON by hand; edit harness labels here and model
 * names and the task list in wharf-swe-tasks.ts.
 */
import data from "./wharf-swe.json";
import { modelName } from "./wharf-swe-tasks";

export { sweTasks } from "./wharf-swe-tasks";

export const wharfSweSource = data.source;
export const wharfSweCommit = data.commit;
export const wharfSweTaskCount = data.taskCount;
export const wharfSweVerified = new Date(`${data.commitDate}T00:00:00Z`).toLocaleDateString("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
  timeZone: "UTC",
});

export type HarnessKey = "copilot-cli" | "claude" | "codex";

export const harnessLabel: Record<HarnessKey, string> = {
  "copilot-cli": "Copilot",
  claude: "Claude Code",
  codex: "Codex",
};

export type SweRun = {
  id: string;
  /** Display name; Claude Code's "claude-opus-5-5" and Copilot's "claude-opus-5.5" share one. */
  model: string;
  harness: HarnessKey;
  version: string;
  passes: number;
  trials: number;
  /** Trials whose patch failed at least one pre-existing test. */
  p2pErrors: number;
  /** Wharf's Score: pass rate minus 0.25 points per P2P error. */
  score: number;
  /** Billed USD per costed trial; null where none was retained (all Codex runs). */
  costPerTrial: number | null;
  /** API-list-price equivalent per trial — Codex only, never a billed charge. */
  apiEstimatePerTrial: number | null;
  agentSeconds: number;
};

export const sweRuns: SweRun[] = data.arms.map((a) => ({
  id: a.id,
  model: modelName(a.model),
  harness: a.harness as HarnessKey,
  version: a.version,
  passes: a.passes,
  trials: a.trials,
  p2pErrors: a.p2pErrors,
  score: a.score,
  costPerTrial: a.costPerTrial,
  apiEstimatePerTrial: a.apiEstimatePerTrial,
  agentSeconds: a.agentSeconds,
}));

export const sweRate = (r: SweRun) => r.passes / r.trials;
export const sweTotalTrials = sweRuns.reduce((sum, r) => sum + r.trials, 0);

/** Copilot CLI revision, e.g. "1.0.114" → 114. */
export const revision = (r: SweRun) => Number(r.version.split(".").at(-1));

/** The models Wharf tracks across Copilot revisions, in the fixed order their colors follow. */
export const trackedModels = ["HydraFusion", "GPT-6.1 Sol", "GPT-6 Astra", "GPT-6 Luna", "Claude Opus 5.5"] as const;

export const copilotRuns = sweRuns.filter((r) => r.harness === "copilot-cli");

/**
 * Release charts start here, matching Wharf's own: earlier runs used different task
 * checksums, so they aren't comparable. They still appear in the results table.
 */
export const firstChartedRevision = 95;
export const latestCopilotRevision = Math.max(...copilotRuns.map(revision));

/** The newest run per harness: Copilot's latest revision plus the Claude Code and Codex runs. */
export const latestRuns = sweRuns.filter(
  (r) => r.harness !== "copilot-cli" || revision(r) === latestCopilotRevision,
);

export const sweRun = (id: string) => {
  const found = sweRuns.find((r) => r.id === id);
  if (!found) throw new Error(`Unknown WharfSWE run: ${id}`);
  return found;
};
